    ws = wb[name]
    print(f"\n--- Sheet: {name} (max_row={ws.max_row}, max_column={ws.max_column}) ---")
    headers = [ws.cell(1, col).value for col in range(1, ws.max_column + 1)]
    print("Headers:", headers)

    # Check missing values per column
    col_missing = {h: 0 for h in headers if h}
    total_rows = ws.max_row - 1

    for row in range(2, ws.max_row + 1):
        for col_idx, h in enumerate(headers, start=1):
            if h:
                val = ws.cell(row, col_idx).value
                if val is None or str(val).strip() == "":
                    col_missing[h] += 1

    print(f"Total data rows: {total_rows}")
    print("Missing counts:")
    for h, cnt in col_missing.items():
        print(f"  {h}: {cnt} / {total_rows} missing ({cnt/total_rows*100:.1f}%)")

